	private static final String PREFIX = "PREFIX ex: <urn:range-order:>\n";
	private static final String WHERE = """
			 WHERE {
			   ?patient ex:type ex:Patient .
			   OPTIONAL {
			     ?patient ex:hasEncounter/ex:hasObservation ?obs .
			     ?obs ex:value ?value . BIND(?value AS ?optValue)
			   }
			   FILTER(?optValue > 60)
			   MINUS { ?patient ex:name ?name . FILTER(CONTAINS(LCASE(STR(?name)), "test")) }
			 }
			""";
	private static final String BODY = PREFIX + "SELECT ?patient ?obs ?value ?optValue" + WHERE;
	private static final String COUNT = PREFIX + "SELECT (COUNT(DISTINCT ?patient) AS ?count)" + WHERE;

