				seedExplicit(nativeRepository, 4);
				seedExplicit(memoryRepository, 4);
				try (InferencerConnection connection = (InferencerConnection) store.getConnection()) {
					seedInferred(connection, nativeRepository.getValueFactory(), 4);
				}
