	private static LmdbStore nativeStore(Path path) {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc").setNativeEvaluationEnabled(true)
				.setDirectAdjacencyEnabled(true).setDirectAdjacencyMode(DirectAdjacencyMode.PREFER)
				.setDirectAdjacencyMaxBytes(1L << 30);
		config.setExperimentalQueryOptimizations(true);
		return new LmdbStore(path.toFile(), config);
	}

	private static void seedExplicit(SailRepository repository, int patients) {
		try (SailRepositoryConnection connection = repository.getConnection()) {
			ValueFactory vf = connection.getValueFactory();
			IRI graph = vf.createIRI("urn:range-order:medical-graph");
			connection.begin();
			for (int patient = 0; patient < patients; patient++) {
				IRI p = vf.createIRI("urn:range-order:patient:" + patient);
				IRI e = vf.createIRI("urn:range-order:encounter:" + patient);
				connection.add(p, vf.createIRI("urn:range-order:type"), vf.createIRI("urn:range-order:Patient"), graph);
				connection.add(p, vf.createIRI("urn:range-order:name"), vf.createLiteral("person " + patient), graph);
				connection.add(p, vf.createIRI("urn:range-order:hasEncounter"), e, graph);
				for (int item = 0; item < 2; item++) {
					IRI o = vf.createIRI("urn:range-order:observation:" + patient + ":" + item);
					connection.add(e, vf.createIRI("urn:range-order:hasObservation"), o, graph);
					connection.add(o, vf.createIRI("urn:range-order:value"), vf.createLiteral(61 + patient * 2 + item), graph);
				}
			}
			connection.commit();
		}
	}

	private static void seedInferred(InferencerConnection connection, ValueFactory vf, int patient) {
		IRI graph = vf.createIRI("urn:range-order:medical-graph");
		IRI p = vf.createIRI("urn:range-order:patient:" + patient);
		IRI e = vf.createIRI("urn:range-order:encounter:" + patient);
		connection.begin();
		connection.addInferredStatement(p, vf.createIRI("urn:range-order:type"), vf.createIRI("urn:range-order:Patient"), graph);
		connection.addInferredStatement(p, vf.createIRI("urn:range-order:name"), vf.createLiteral("person " + patient), graph);
		connection.addInferredStatement(p, vf.createIRI("urn:range-order:hasEncounter"), e, graph);
		for (int item = 0; item < 2; item++) {
			IRI o = vf.createIRI("urn:range-order:observation:" + patient + ":" + item);
			connection.addInferredStatement(e, vf.createIRI("urn:range-order:hasObservation"), o, graph);
			connection.addInferredStatement(o, vf.createIRI("urn:range-order:value"), vf.createLiteral(61 + patient * 2 + item), graph);
		}
		connection.commit();
	}

	private static Component component(String label, MultiJoinPlan plan, RowState row) throws Exception {
		Work work = new Work();
		SingletonSet target = new SingletonSet();
		target.setRuntimeTelemetryEnabled(true);
		LmdbNativeRuntimePlan.Invocation invocation = LmdbNativeExplain.recordRuntimeEntryPlan(target, plan,
				row.layout, row.boundMask());
		row.runtimePlan = invocation;
		row.probeWorkObserver = work;
		Map<String, Long> bag = new TreeMap<>();
		long rows = 0L;
		try {
			try (RowCursor cursor = plan.open(row)) {
				while (cursor.next()) {
					Map<String, Object> mapping = new TreeMap<>();
					for (int slot = 0; slot < row.slots.length; slot++) {
						mapping.put(row.layout.slotName(slot), term(row.source.lazyValue(row.slots[slot])));
					}
					bag.merge(json(mapping), 1L, Long::sum);
					rows++;
				}
			}
		} finally {
			invocation.complete();
			row.probeWorkObserver = null;
			row.runtimePlan = null;
			emit(map("case", label, "classification", "EXPLICIT_COMPONENT_CURSOR", "boundMaskAfterClose", row.boundMask(),
					"rows", rows, "fullBag", bag, "work", work.receipt(), "actualRuntimePlan",
					target.getStringMetricActual(TelemetryMetricNames.RUNTIME_PHYSICAL_PLAN)));
		}
		return new Component(bag, rows, work);
	}

	private static Bag publicBag(SailRepositoryConnection connection, String query, boolean inferred, String label) {
		TupleQuery prepared = connection.prepareTupleQuery(query);
		prepared.setIncludeInferred(inferred);
		prepared.setMaxExecutionTime(120);
		assertEquals(inferred, prepared.getIncludeInferred());
		Map<String, Long> bag = new TreeMap<>();
		List<Object> metadata = new ArrayList<>();
		long rows = 0L;
		long count = -1L;
		try (var result = prepared.evaluate()) {
			while (result.hasNext()) {
				BindingSet row = result.next();
				Map<String, Object> mapping = new TreeMap<>();
				for (String name : new TreeSet<>(row.getBindingNames())) {
					assertTrue(row.hasBinding(name));
					mapping.put(name, term(row.getValue(name)));
				}
				assertEquals(query.equals(COUNT) ? Set.of("count") : Set.of("patient", "obs", "value", "optValue"),
						row.getBindingNames(), "exact complete public mapping domain");
				bag.merge(json(mapping), 1L, Long::sum);
				BindingSetOrigin origin = BindingSetOrigin.of(row);
				metadata.add(map("domain", new TreeSet<>(row.getBindingNames()), "tracked",
						BindingSetOrigin.isTrackedInput(row), "local", origin.localNames(), "request", origin.requestNames(),
						"retained", origin.retainedNamesForTransport(() -> { }), "parameters", origin.retainedParametersForTransport()));
				if (row.hasBinding("count")) {
					count = ((Literal) row.getValue("count")).longValue();
				}
				rows++;
			}
		}
		emit(map("case", label, "separateInvocation", true, "includeInferred", inferred, "rows", rows,
				"fullBag", bag, "metadata", metadata, "resultCloseReturned", true));
		return new Bag(bag, rows, count);
	}

	private static void telemetry(SailRepositoryConnection connection, String query, String label) {
		TupleQuery prepared = connection.prepareTupleQuery(query);
		prepared.setIncludeInferred(true);
		prepared.setMaxExecutionTime(120);
		Explanation explanation = prepared.explain(Explanation.Level.Telemetry);
		List<Object> nodes = new ArrayList<>();
		List<String> paths = new ArrayList<>();
		actualNodes(explanation.toGenericPlanNode(), "root", nodes, paths);
		emit(map("case", label, "separateFromBagAndOtherTelemetry", true, "actualExplanationJSON", explanation.toJson(),
				"actualEvaluatedAlgebra", String.valueOf(explanation.tupleExpr()), "nodes", nodes, "actualNativePaths", paths,
				"nativePathAvailability", paths.isEmpty() ? "UNEXPOSED_OR_NOT_SELECTED" : "ACTUAL_PATH_PRESENT",
				"privateOwnerFields", "UNEXPOSED_NOT_INFERRED_FROM_COMPONENT"));
		assertNoTimeout(explanation.toGenericPlanNode());
	}

	private static void actualNodes(GenericPlanNode node, String path, List<Object> nodes, List<String> paths) {
		Map<String, String> actual = node.getStringMetricsActual();
		if (actual != null && actual.get(TelemetryMetricNames.NATIVE_EXECUTION_PATH) != null) {
			paths.add(path + "=" + actual.get(TelemetryMetricNames.NATIVE_EXECUTION_PATH));
		}
		nodes.add(map("coordinate", path, "type", node.getType(), "algorithm", node.getAlgorithm(),
				"physicalPlanPrelude", node.getPhysicalPlanPrelude(), "actualLong", node.getLongMetricsActual(),
				"actualDouble", node.getDoubleMetricsActual(), "actualString", actual,
				"strategyPreviewClassification", "ANY_PREVIEW_IN_FULL_JSON_IS_NOT_AN_OPENED_WINNER"));
		if (node.getPlans() != null) {
			for (int i = 0; i < node.getPlans().size(); i++) {
				actualNodes(node.getPlans().get(i), path + "/" + i, nodes, paths);
			}
		}
	}

	private static void assertNoTimeout(GenericPlanNode node) {
		assertTrue(!Boolean.TRUE.equals(node.getTimedOut()), "actual public Telemetry timed out");
		if (node.getPlans() != null) {
			for (GenericPlanNode child : node.getPlans()) {
				assertNoTimeout(child);
			}
		}
	}

	private static StatementPattern pattern(ValueFactory vf, String subject, String predicate, String object) {
		return new StatementPattern(Var.of(subject), constant(vf, "_" + predicate, predicate), Var.of(object));
	}

	private static Var constant(ValueFactory vf, String name, String value) {
		return Var.of(name, vf.createIRI("urn:range-order:" + value), true, true);
	}

	private static Object term(Value value) {
		if (value == null) return map("state", "PRESENT_NULL");
		if (value instanceof IRI iri) return map("kind", "IRI", "lexical", iri.stringValue());
		if (value instanceof Literal literal) return map("kind", "LITERAL", "lexical", literal.getLabel(),
				"datatype", literal.getDatatype().stringValue(), "language", literal.getLanguage().orElse(null),
				"direction", literal.getBaseDirection().name());
		throw new AssertionError("fixture emitted unsupported RDF term kind: " + value.getClass().getName());
	}

	private record Component(Map<String, Long> bag, long rows, Work work) { }
	private record Bag(Map<String, Long> bag, long rows, long countValue) { }

	private static final class Work implements NativeLmdbQuerySource.AdjacencyAccessObserver {
		long selectedCalls;
		long physicalScanned;
		long physicalMeasurements;
		long returnedRowMeasurements;
		long censoredMeasurements;
		final List<Object> events = new ArrayList<>();

		@Override
		public void access(boolean adjacency, String reason, StatementOrder order, long s, long p, long o, long c) {
			events.add(map("kind", "ACCESS", "adjacency", adjacency, "reason", reason, "order", String.valueOf(order),
					"s", s, "p", p, "o", o, "c", c));
		}

		@Override
		public void selected(boolean adjacency, String reason, StatementOrder order, long s, long p, long o, long c) {
			selectedCalls++;
			events.add(map("kind", "SELECTED", "adjacency", adjacency, "reason", reason, "order", String.valueOf(order),
					"s", s, "p", p, "o", o, "c", c));
		}

		@Override
		public void measurement(boolean adjacency, long scanned, long matched, long filtered, boolean censored,
				boolean physicalScanCount) {
			if (physicalScanCount) {
				physicalScanned = Math.addExact(physicalScanned, scanned);
				physicalMeasurements++;
			} else returnedRowMeasurements++;
			if (censored) censoredMeasurements++;
			events.add(map("kind", "MEASUREMENT", "adjacency", adjacency, "scanned", scanned, "matched", matched,
					"filtered", filtered, "censored", censored, "physicalScanCount", physicalScanCount));
		}

		@Override
		public void measurement(boolean adjacency, long scanned, long matched, long filtered, boolean censored) {
			measurement(adjacency, scanned, matched, filtered, censored, false);
		}

		boolean hasUncensoredPhysicalReceipts() {
			return physicalMeasurements > 0L && returnedRowMeasurements == 0L && censoredMeasurements == 0L;
		}

		Object receipt() {
			return map("selectedAccessCalls", selectedCalls, "physicalScanned", physicalScanned,
					"physicalMeasurements", physicalMeasurements, "returnedRowMeasurements", returnedRowMeasurements,
					"censoredMeasurements", censoredMeasurements, "events", events,
					"coverage", "PARTIAL_UNPROVEN_NOT_EVERY_SELECTED_ACCESS",
					"unmeasured", "decode/seek CPU and generated key-domain work are not inferred from these counters");
		}
	}

	private static Map<String, Object> map(Object... values) {
		Map<String, Object> result = new LinkedHashMap<>();
		for (int i = 0; i < values.length; i += 2) result.put((String) values[i], values[i + 1]);
		return result;
	}

	private static void emit(Object value) {
		System.out.println("RDF4J_RANGE_WORK_PUBLIC " + json(value));
	}

	private static String json(Object value) {
		if (value == null) return "null";
		if (value instanceof Number || value instanceof Boolean) return value.toString();
		if (value instanceof Map<?, ?> map) {
			List<String> entries = new ArrayList<>();
			for (var entry : map.entrySet()) entries.add(json(String.valueOf(entry.getKey())) + ":" + json(entry.getValue()));
			return "{" + String.join(",", entries) + "}";
		}
		if (value instanceof Iterable<?> entries) {
			List<String> result = new ArrayList<>();
			for (Object entry : entries) result.add(json(entry));
			return "[" + String.join(",", result) + "]";
		}
		return "\"" + value.toString().replace("\\", "\\\\").replace("\"", "\\\"")
				.replace("\n", "\\n").replace("\r", "\\r").replace("\t", "\\t") + "\"";
	}
